import{_ as t,o as a,c as i,a1 as s}from"./chunks/framework.DdbKPUhY.js";const p=JSON.parse('{"title":"Memory Safety Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/memory-safety.md","filePath":"spec/memory-safety.md"}'),r={name:"spec/memory-safety.md"};function n(o,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="memory-safety-spec" tabindex="-1">Memory Safety Spec <a class="header-anchor" href="#memory-safety-spec" aria-label="Permalink to &quot;Memory Safety Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>UVHTTP guarantees memory safety for long-running production services and embedded devices. This spec defines the memory safety criteria that all code must satisfy before being merged.</p><h2 id="sanitizer-gates" tabindex="-1">Sanitizer Gates <a class="header-anchor" href="#sanitizer-gates" aria-label="Permalink to &quot;Sanitizer Gates&quot;">​</a></h2><h3 id="addresssanitizer-asan" tabindex="-1">AddressSanitizer (ASan) <a class="header-anchor" href="#addresssanitizer-asan" aria-label="Permalink to &quot;AddressSanitizer (ASan)&quot;">​</a></h3><ul><li><strong>Requirement</strong>: The full test suite (91 tests) must pass with zero findings under ASan with leak detection enabled.</li><li><strong>Build</strong>: <code>cmake -B build_asan -DCMAKE_BUILD_TYPE=Debug -DENABLE_ASAN=ON</code></li><li><strong>Run</strong>: <code>cd build_asan &amp;&amp; ctest --output-on-failure</code></li><li><strong>CI gate</strong>: <code>.github/workflows/ci-pr.yml</code> — every PR must pass ASan</li></ul><h3 id="undefinedbehaviorsanitizer-ubsan" tabindex="-1">UndefinedBehaviorSanitizer (UBSan) <a class="header-anchor" href="#undefinedbehaviorsanitizer-ubsan" aria-label="Permalink to &quot;UndefinedBehaviorSanitizer (UBSan)&quot;">​</a></h3><ul><li><strong>Requirement</strong>: The full test suite must pass with zero findings under UBSan.</li><li><strong>Build</strong>: <code>cmake -B build_ubsan -DCMAKE_BUILD_TYPE=Debug -DENABLE_UBSAN=ON</code></li><li><strong>Run</strong>: <code>cd build_ubsan &amp;&amp; ctest --output-on-failure</code></li><li><strong>CI gate</strong>: <code>.github/workflows/ci-nightly.yml</code> — nightly run</li></ul><h3 id="why-separate-builds" tabindex="-1">Why separate builds <a class="header-anchor" href="#why-separate-builds" aria-label="Permalink to &quot;Why separate builds&quot;">​</a></h3><p>ASan and UBSan cannot be combined in a single build. Both must be green.</p><h2 id="bug-classes-—-zero-tolerance" tabindex="-1">Bug Classes — Zero Tolerance <a class="header-anchor" href="#bug-classes-—-zero-tolerance" aria-label="Permalink to &quot;Bug Classes — Zero Tolerance&quot;">​</a></h2><p>The following bug classes are explicitly prohibited. The CHANGELOG documents all fixes applied to reach zero findings.</p><table tabindex="0"><thead><tr><th>Bug Class</th><th>Detection</th><th>Prevention</th></tr></thead><tbody><tr><td>Heap use-after-free</td><td>ASan</td><td>NULL pointers after free, freed flag</td></tr><tr><td>Heap buffer overflow</td><td>ASan</td><td>Bounds checking, snprintf, safe string ops</td></tr><tr><td>Stack buffer overflow</td><td>ASan</td><td>Fixed-size buffers, snprintf</td></tr><tr><td>Stack buffer underflow</td><td>ASan</td><td>Array index validation</td></tr><tr><td>Memory leak</td><td>ASan (leak detection)</td><td>Alloc/free pairing, cleanup functions</td></tr><tr><td>Double free</td><td>ASan</td><td>freed flag, NULL checks</td></tr><tr><td>Signed integer overflow</td><td>UBSan</td><td>Bounds checking</td></tr><tr><td>Invalid shift</td><td>UBSan</td><td>Platform-specific shift handling (32-bit)</td></tr><tr><td>Null pointer dereference</td><td>UBSan</td><td>NULL checks on all public API params</td></tr><tr><td>Misalignment</td><td>UBSan</td><td>Static assertions on struct layout</td></tr></tbody></table><h2 id="reproduce-command" tabindex="-1">Reproduce Command <a class="header-anchor" href="#reproduce-command" aria-label="Permalink to &quot;Reproduce Command&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify-memory-safety</span></span></code></pre></div><p>This builds and runs both ASan and UBSan configurations. A clean run prints:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==&gt; PASS: full suite clean under ASan and UBSan (91/91 each).</span></span></code></pre></div><h2 id="defense-in-depth" tabindex="-1">Defense in Depth <a class="header-anchor" href="#defense-in-depth" aria-label="Permalink to &quot;Defense in Depth&quot;">​</a></h2><p>Beyond sanitizers, the codebase applies:</p><ol><li><p><strong>Compile-time hardening</strong>:</p><ul><li><code>-Werror</code> with <code>-Wall -Wextra -Wformat=2 -Wformat-security</code></li><li><code>-fstack-protector-strong</code>, <code>-fno-common</code></li><li>Full RELRO (<code>-Wl,-z,relro,now</code>)</li><li><code>_FORTIFY_SOURCE=2</code></li></ul></li><li><p><strong>Safe string operations</strong>: No <code>strcpy</code> or <code>sprintf</code>. All string operations use <code>snprintf</code> or <code>uvhttp_safe_strcpy</code> (which wraps snprintf).</p></li><li><p><strong>Input validation</strong>: URL length, path traversal, header size/format, body size limits are checked before any buffer operation.</p></li><li><p><strong>Response splitting guards</strong>: All header values are checked for control characters before emission.</p></li><li><p><strong>Idempotent cleanup</strong>: All <code>*_cleanup</code> / <code>*_free_resources</code> paths NULL pointers after freeing and guard on a <code>freed</code> flag.</p></li></ol><h2 id="fuzzing" tabindex="-1">Fuzzing <a class="header-anchor" href="#fuzzing" aria-label="Permalink to &quot;Fuzzing&quot;">​</a></h2><p>The router module is fuzzed nightly with libFuzzer + ASan:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./fuzz_router</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -max_total_time=60</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -max_len=256</span></span></code></pre></div><p>The fuzzer already found one real bug (heap-buffer-overflow in <code>add_route_method</code>) that the unit tests never hit.</p><h2 id="leak-policy" tabindex="-1">Leak Policy <a class="header-anchor" href="#leak-policy" aria-label="Permalink to &quot;Leak Policy&quot;">​</a></h2><ul><li><strong>Zero tolerance</strong>: Any leak detected by ASan is a release blocker</li><li><strong>False positives</strong>: ASan false positives (e.g., stack frame reuse) must be documented with a <code>no_sanitize(&quot;address&quot;)</code> attribute and a comment explaining the false positive</li><li><strong>Leak detection</strong>: ASan is configured with <code>detect_leaks=1</code></li></ul>',26)])])}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
